162	/** The result count a button shows once its action is done (how many were added, made, opened).
163	 *  `was` is what the cell showed before the click. The count is taken once it differs from `was`,
164	 *  or once the cell was seen cleared and shown again (README: a result is cleared when its button
165	 *  is pressed again). Two identical results in a row can look the same on screen for the whole
166	 *  wait: then, with no error showing and a value in the cell, that value is taken rather than
167	 *  failing a step the app did take. */
168	async function countAfter(page: Page, cell: Locator, error: Locator, what: string, was: string): Promise<string | null> {
169	  let cleared = false;
170	  const done = async () => {
171	    if ((await cell.count()) === 0) return false;
172	    const now = await shown(cell);
173	    if (now === '') { cleared = true; return false; }
174	    return now !== was || was === '' || cleared;
175	  };
176	  try {
177	    return (await until(page, done, error, what)) ? await shown(cell) : null;
178	  } catch (e) {
179	    if (await error.isVisible().catch(() => false)) return null;
180	    if ((await cell.count()) > 0 && (await shown(cell)) !== '') return shown(cell);
181	    throw e;
182	  }
183	}
