187	// Each sign-in gets its own browser context, so users on one sheet act independently. A context
188	// is closed once the test that opened it has finished: the test runner leaves them open, and a
189	// whole suite of open pages, each still running the app, would exhaust the machine.
190	const opened = new Map<BrowserContext, string>();   // context -> id of the test that opened it
191	
192	export async function userPage(browser: Browser, user: string, sheet: string): Promise<Page> {
193	  let owner = '';
194	  try { owner = test.info().testId; } catch { /* outside a test: nothing to tidy by */ }
195	  for (const [c, t] of opened) {
196	    if (t === owner) continue;
197	    opened.delete(c);
198	    await c.close().catch(() => { /* already gone */ });
199	  }
200	  const context = await browser.newContext();
201	  opened.set(context, owner);
202	  const page = await context.newPage();
203	  page.setDefaultTimeout(LOAD_WAIT);     // an element an action needs that never shows fails here, not at the test's limit
204	  await page.goto('/');
205	  await page.getByTestId('signin-name').fill(user);
206	  await page.getByTestId('signin-submit').click();
207	  await expect(page.getByTestId('current-user')).toHaveText(user, { timeout: LOAD_WAIT });
208	  await loadSheet(page, sheet);
209	  return page;
210	}
