806	/** A refused save leaves the editor open (the contract says a refusal changes nothing): close it
807	 *  with the cancel button when the screen has one, so the shared form is back to adding. */
808	async function cancelOpenEditor(c: Locator): Promise<void> {
809	  const cancel = c.getByTestId('claim-cancel');
810	  if ((await cancel.count()) > 0 && await cancel.isVisible().catch(() => false)) await cancel.click().catch(() => undefined);
